(()=>{'use strict';
const root=document.querySelector('#moreLabs'),M=ScienceModels,reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const meta={
 motion:['Newton’s laws','A force changes motion.','Double the mass while keeping the force fixed. How should the velocity–time graph change?','Impact 10P02V · Stile: The first, second and third laws of motion; Acceleration and graphs.','Acceleration halves because a = Fnet/m. The velocity–time slope halves. After the push ends, zero net force means constant velocity in this frictionless model.'],
 evolution:['Evolution','Selection acts on variation.','If the environment changes, can the allele that was favoured begin to decrease?','Impact 10B02V: existing variation, selection pressures and changes in allele frequencies.','Yes. Relative reproductive success depends on the environment. Populations change over generations; individuals do not change their inherited alleles because they need to.'],
 atoms:['Periodic table','Count. Arrange. Compare.','What repeats when you compare lithium with sodium, or neon with argon?','Impact 10C01V · Stile: The structure of atoms; Electron configurations; Valence electrons.','Lithium and sodium each have one outer-shell electron. Neon and argon have full outer shells. Similar outer-shell arrangements help explain recurring chemical properties.'],
 reactions:['Chemical reactions','Atoms stay. Bonds change.','Can you balance an equation by changing the small numbers inside a chemical formula?','Stile: Balancing chemical equations; Reaction types. Impact 10C02V resources were pending at review.','No. Change coefficients in front of formulas. Changing a subscript changes the substance. The number of atoms of each element must be equal before and after a chemical reaction.'],
 immunity:['Immunology','Recognise. Respond. Remember.','Why can a response to a familiar antigen be faster than the first response?','Supplementary conceptual model: CDC Principles of Vaccination. Impact 10B04V lesson resources were pending; no matching Stile lesson found.','Some antigen-specific B and T cells persist as memory cells after a response. They can respond more rapidly on later exposure. Memory is specific, and protection varies with pathogen, vaccine and time.']
};let topic='motion',time=0,run=false,raf=0,last=0,gen=0,p=.5,history=[.5],phase=0;
const state={v:6,r1:10,r2:10,parallel:false,closed:true,f:4,m:2,cut:false,third:false,environment:'A',selection:.5,z:11,scale:1,observer:0,albedo:.3,epsilon:.78,reaction:0,c1:1,c2:1,c3:1};
const Q=s=>root.querySelector(s),T=(x,y,s,size=16,color='#173b3b')=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="${color}">${s}</text>`,line=(x,y,a,b,col='#173b3b',w=3)=>`<path d="M${x} ${y}L${a} ${b}" stroke="${col}" stroke-width="${w}" fill="none"/>`,circle=(x,y,r,c)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`,svg=(c,label)=>`<svg viewBox="0 0 600 340" role="img" aria-label="${label}"><defs><marker id="arrowLab" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#bd693f"/></marker></defs>${c}</svg>`,arrow=(x,y,a,b)=>`<path d="M${x} ${y}L${a} ${b}" stroke="#bd693f" stroke-width="4" marker-end="url(#arrowLab)"/>`;
root.innerHTML=`<div class="sectionhead"><div><div class="eyebrow">03 / EXPLORE THE REST</div><h2>Make a prediction. Test the model.</h2></div><span class="pill">5 TOPIC EXPLORERS</span></div><p class="small">Start with Newton’s laws and evolution. Each explorer connects a visual model to an exam explanation. These are revision models, not complete unit lessons.</p><div class="labchoices">${Object.entries(meta).map(([key,d])=>`<button data-explorer="${key}" aria-pressed="false">${d[0]}</button>`).join('')}</div><div id="explorerBody"></div>`;
function pause(){run=false;cancelAnimationFrame(raf);if(Q('#exPlay'))Q('#exPlay').textContent='▶ Play';}
function range(id,label,min,max,step,val,unit=''){return `<label for="ex-${id}">${label} <output id="out-${id}">${val}${unit}</output><input type="range" id="ex-${id}" data-key="${id}" min="${min}" max="${max}" step="${step}" value="${val}" data-unit="${unit}"></label>`;}
function select(id,label,options){return `<label for="ex-${id}">${label}<select id="ex-${id}" data-key="${id}">${options.map(([v,n])=>`<option value="${v}" ${String(state[id])===String(v)?'selected':''}>${n}</option>`).join('')}</select></label>`;}
function checkbox(id,label){return `<label class="excheck"><input type="checkbox" data-key="${id}" ${state[id]?'checked':''}> ${label}</label>`;}
function render(){pause();time=0;phase=0;const d=meta[topic];root.querySelectorAll('[data-explorer]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.explorer===topic));Q('#explorerBody').innerHTML=`<div class="labgrid"><div class="labvisual"><div class="eyebrow">${d[0]} · interactive model</div><div id="exCanvas"></div><div id="exReadout" class="exreadout" aria-live="polite"></div><div id="exInputs" class="exinputs"></div><div class="controls" id="exControls"></div><p id="exLimit" class="small"></p></div><aside class="labnotes"><h3>${d[1]}</h3><div class="reviewbox"><span class="eyebrow">PREDICT FIRST</span><p>${d[2]}</p></div><p id="exExplain"></p><details><summary>Check your prediction</summary><p>${d[4]}</p></details><details><summary>Try an exam explanation</summary><p>Describe the change you made. Use a value or visible pattern from the model as evidence. Explain it with the relevant scientific principle, then state one model limitation.</p></details><p class="small"><b>Resource connection</b><br>${d[3]}</p><div id="exSource"></div><button id="exQuiz" class="primary">Practise exam questions →</button></aside></div>`;
Q('#exQuiz').onclick=()=>{pause();window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:topic}));};let controls='';
if(topic==='motion')controls=range('f','Net force during push',0,10,1,state.f,' N')+range('m','Cart A mass',1,5,1,state.m,' kg')+checkbox('cut','Release after 2 seconds — first law')+checkbox('third','Third-law pair: two carts push apart for 2 seconds');
if(topic==='evolution')controls=select('environment','Environment favours',[['A','A allele'],['a','a allele'],['neutral','Neither allele']])+range('selection','Selection strength',0,.9,.1,state.selection);
if(topic==='atoms')controls=range('z','Atomic number',1,20,1,state.z);
if(topic==='reactions')controls=select('reaction','Choose equation',[[0,'Hydrogen + oxygen → water'],[1,'Magnesium + oxygen → magnesium oxide'],[2,'Nitrogen + hydrogen → ammonia']])+range('c1','First coefficient',1,6,1,state.c1)+range('c2','Second coefficient',1,6,1,state.c2)+range('c3','Product coefficient',1,6,1,state.c3);
Q('#exInputs').innerHTML=controls;
const animate=['motion'].includes(topic);Q('#exControls').innerHTML=animate?`<button id="exPlay" class="primary" ${reduce?'disabled':''}>${reduce?'Reduced motion · use steps':'▶ Play'}</button><button id="exStep">Step forward</button><button id="exReset">Reset time</button>`:topic==='evolution'?'<button id="exStep" class="primary">Next generation</button><button id="exReset">Reset population</button>':topic==='immunity'?'<button id="exPrev">← Previous</button><button id="exStep" class="primary">Next stage →</button><button id="exReset">Reset sequence</button>':'';
Q('#exInputs').querySelectorAll('input,select').forEach(e=>e.oninput=()=>{pause();let key=e.dataset.key;state[key]=e.type==='checkbox'?e.checked:key==='parallel'?e.value==='true':['environment'].includes(key)?e.value:Number(e.value);if(Q('#out-'+key))Q('#out-'+key).textContent=state[key]+(e.dataset.unit||'');if(topic!=='evolution')time=0;draw();});
if(Q('#exPlay'))Q('#exPlay').onclick=()=>{if(run){pause();return}if(time>=8)time=0;run=true;last=performance.now();Q('#exPlay').textContent='Ⅱ Pause';raf=requestAnimationFrame(tick)};
if(Q('#exStep'))Q('#exStep').onclick=()=>{pause();if(topic==='evolution'){if(gen<20){p=M.selection(p,state.selection,state.environment);gen++;history.push(p)}}else if(topic==='immunity')phase=Math.min(4,phase+1);else time=Math.min(8,time+1);draw()};if(Q('#exPrev'))Q('#exPrev').onclick=()=>{phase=Math.max(0,phase-1);draw()};if(Q('#exReset'))Q('#exReset').onclick=()=>{pause();time=0;phase=0;gen=0;p=.5;history=[.5];draw()};draw();}
function tick(now){if(!run)return;time=Math.min(8,time+Math.min(.05,(now-last)/1000));last=now;draw();if(time>=8)pause();else raf=requestAnimationFrame(tick)}
function display(c,label,readout,explain,limit){Q('#exCanvas').innerHTML=svg(c,label);Q('#exReadout').textContent=readout;Q('#exExplain').textContent=explain;Q('#exLimit').textContent=limit;}

function motion(){const s=state,third=s.third,d=M.motion(s.f,s.m,time,third||s.cut),other=M.motion(s.f,4,time,true),x=third?280-d.x*1.5:55+d.x*1.25;let c=line(20,150,580,150)+`<rect x="${x}" y="90" width="55" height="40" rx="8" fill="#238780"/>`+circle(x+12,140,10,'#173b3b')+circle(x+43,140,10,'#173b3b')+T(x+27,78,`A · ${s.m} kg`,13);
if(third){let b=345+other.x*1.5;c+=`<rect x="${b}" y="90" width="55" height="40" rx="8" fill="#5074b6"/>`+circle(b+12,140,10,'#173b3b')+circle(b+43,140,10,'#173b3b')+T(b+27,78,'B · 4 kg',13);if(time<2&&s.f)c+=arrow(x,110,x-s.f*5,110)+arrow(b+55,110,b+55+s.f*5,110);c+=T(300,30,'Equal opposite forces act on different carts',17);}else if(d.a)c+=arrow(x+55,105,x+55+s.f*8,105);
c+=line(55,190,55,300)+line(55,300,550,300)+T(290,330,'Time (0–8 s)',13)+T(125,180,'Velocity (m/s)',13);const maxV=Math.max(1,M.motion(s.f,s.m,8,third||s.cut).v);let path='';for(let t=0;t<=time+.001;t+=.05){let v=M.motion(s.f,s.m,t,third||s.cut).v;path+=(t===0?'M':'L')+(55+t*60)+' '+(300-v/maxV*95)}c+=`<path d="${path}" fill="none" stroke="#238780" stroke-width="3"/>`+T(28,210,maxV.toFixed(1),12)+T(30,304,'0',12);
display(c,'Cart motion and velocity graph. '+(third?'The graph shows the magnitude of cart A velocity to the left.':'Cart A moves right.'),`t = ${time.toFixed(1)} s | A: acceleration ${d.a.toFixed(2)} m/s², ${third?'speed':'velocity'} ${d.v.toFixed(2)} m/s | displacement ${third?'−':''}${d.x.toFixed(2)} m`,third?'During the push each cart exerts an equal, opposite force on the other. These forces do not cancel on either cart because they act on different objects. Unequal masses accelerate differently. After 2 s both coast. The graph shows cart A’s speed; its velocity is to the left.':'The graph slope is acceleration: a = Fnet/m. In release mode, the push stops at 2 s but the cart keeps its velocity. A moving object does not need a continuing net force to keep moving.','Horizontal frictionless model; gravity and support force balance vertically. Carts start at rest. Positions are schematic. Third-law interaction is idealised as a 2 s push between separated carts.');}
function evolution(){let c=T(155,25,'Expected genotype proportions',17),nAA=Math.round(p*p*60),nAa=Math.round(2*p*(1-p)*60);for(let i=0;i<60;i++){let col=i<nAA?'#238780':i<nAA+nAa?'#d1ad52':'#5074b6';c+=circle(35+(i%10)*25,60+Math.floor(i/10)*32,9,col);}c+=T(155,275,'AA teal · Aa gold · aa blue',13)+line(335,60,335,250)+line(335,250,570,250)+T(450,280,'Generation (0–20)',13)+T(450,25,'Frequency of allele A',17)+T(315,65,'1',12)+T(315,255,'0',12);let path=history.map((v,i)=>(i?'L':'M')+(335+i*11.5)+' '+(250-v*190)).join('');c+=`<path d="${path}" fill="none" stroke="#bd693f" stroke-width="3"/>`;display(c,'Genotype symbols and allele A frequency over generations',`Generation ${gen} | A ${(p*100).toFixed(1)}% | a ${((1-p)*100).toFixed(1)}%`, 'Variation exists at the start. The selected environment changes relative reproductive success, then random mating produces the next generation. Switch the environment mid-run to reverse the selective advantage. A neutral environment preserves allele frequency in this deterministic model.','Large-population, one-locus model; no mutation, migration or genetic drift. AA/Aa/aa fitness is 1, 1−s/2, 1−s when A is favoured (reversed for a). Dots are rounded expected proportions, not individual organisms changing colour.');Q('#exStep').disabled=gen>=20;}
const elements=['','Hydrogen','Helium','Lithium','Beryllium','Boron','Carbon','Nitrogen','Oxygen','Fluorine','Neon','Sodium','Magnesium','Aluminium','Silicon','Phosphorus','Sulfur','Chlorine','Argon','Potassium','Calcium'];
function atoms(){const z=state.z,shell=M.shells(z);let c=circle(200,165,28,'#173b3b')+T(200,171,z+' p⁺',15,'white');shell.forEach((n,i)=>{const r=45+i*24;c+=`<circle cx="200" cy="165" r="${r}" fill="none" stroke="#a1b5ac"/>`;for(let e=0;e<n;e++){const a=e/n*Math.PI*2;c+=circle(200+r*Math.cos(a),165+r*Math.sin(a),6,i===shell.length-1?'#bd693f':'#5074b6')}});c+=T(450,110,elements[z],23)+T(450,150,'Atomic number '+z,17)+T(450,185,'Shells: '+shell.join(', '),17)+T(450,220,'Outer electrons: '+shell.at(-1),17)+T(300,315,'Select 3 → 11, or 10 → 18, to compare repeating patterns',14);display(c,'Shell model of a neutral '+elements[z]+' atom',`${z} protons | ${z} electrons | ${shell.length} occupied shell${shell.length===1?'':'s'}`,'Atomic number counts protons and identifies the element. Neutral atoms have the same number of electrons as protons. Across these early elements, similar outer-shell arrangements recur and help explain groups with related properties.','Simplified shell model for neutral ground-state atoms 1–20; circles are energy levels, not literal electron orbits. Neutrons and isotope variation are omitted. Shell filling beyond calcium is more complex.');}


const eqs=[{forms:['H₂','O₂','H₂O'],atoms:[[2,0],[0,2],[2,1]],names:['H','O'],answer:'2 H₂ + O₂ → 2 H₂O'}, {forms:['Mg','O₂','MgO'],atoms:[[1,0],[0,2],[1,1]],names:['Mg','O'],answer:'2 Mg + O₂ → 2 MgO'}, {forms:['N₂','H₂','NH₃'],atoms:[[2,0],[0,2],[1,3]],names:['N','H'],answer:'N₂ + 3 H₂ → 2 NH₃'}];
function reactions(){const e=eqs[state.reaction],cs=[state.c1,state.c2,state.c3],left=e.names.map((_,i)=>cs[0]*e.atoms[0][i]+cs[1]*e.atoms[1][i]),right=e.names.map((_,i)=>cs[2]*e.atoms[2][i]),balanced=left.every((v,i)=>v===right[i]);let c=T(300,40,`${cs[0]} ${e.forms[0]} + ${cs[1]} ${e.forms[1]} → ${cs[2]} ${e.forms[2]}`,27)+T(160,85,'Reactant atoms',16)+T(440,85,'Product atoms',16);for(let side=0;side<2;side++)for(let row=0;row<2;row++){let count=(side?right:left)[row];c+=T(side?440:160,115+row*90,`${e.names[row]}: ${count}`,16);for(let i=0;i<count;i++)c+=circle((side?335:55)+(i%10)*23,140+row*90+Math.floor(i/10)*20,7,row?'#5074b6':'#bd693f');}c+=T(300,325,balanced?'Balanced — every element is conserved':'Not yet balanced — compare each element',18);display(c,'Atom counts before and after a chemical reaction',balanced?'Balanced equation ✓':'Adjust coefficients to conserve each element', 'Each coefficient multiplies the entire formula. Watch both elements: fixing one count can change another. Atoms are rearranged into new substances; they are not created or destroyed. A balanced multiple is valid; convention uses the smallest whole-number coefficients.','The dots count atoms, not molecular arrangements or a reaction mechanism. This explorer covers conservation and balancing, not every reaction type.');if(!Q('#balanceAnswer'))Q('.labnotes').insertAdjacentHTML('beforeend','<details id="balanceAnswer"><summary>Reveal simplest balanced equation</summary><p></p></details>');Q('#balanceAnswer p').textContent=e.answer;}
function immunity(){const names=['Barrier and encounter','Recognition and activation','Clonal expansion and response','Memory persists','Later exposure'],desc=['Skin and other barriers help prevent entry. If a pathogen enters, innate responses begin; adaptive responses may follow.','Cells with receptors that recognise the antigen are activated with appropriate signals. Helper T cells can support B-cell responses.','Selected cells multiply. Plasma cells produce antibodies; other immune cells act on pathogens or infected cells. Different pathogens require different responses.','Most activated cells decline after the response. Some B and T cells remain as memory cells. Antibodies and memory are related but are not identical.','On later exposure to the same antigen, memory cells can mount a faster response. This is a simplified explanation of immune memory, not a promise of complete or lifelong protection.'];let c=T(300,35,names[phase],23);for(let i=0;i<5;i++)c+=circle(100+i*100,85,15,i<=phase?'#238780':'#d7e1d6')+T(100+i*100,91,String(i+1),14,i<=phase?'white':'#173b3b');let n=phase===2?12:phase===4?16:phase===3?4:2;for(let i=0;i<n;i++){let x=100+i%8*56,y=170+Math.floor(i/8)*60;c+=circle(x,y,17,phase===3?'#5074b6':'#238780');if(phase>=2&&phase!==3)c+=line(x+25,y-10,x+25,y+12,'#bd693f',2)+line(x+25,y-10,x+18,y-18,'#bd693f',2)+line(x+25,y-10,x+32,y-18,'#bd693f',2);}c+=T(300,310,phase===3?'Blue symbols: memory cells':'Teal: responding cells · orange Y: antibody symbols',14);display(c,names[phase]+'. '+desc[phase],`Stage ${phase+1} of 5`,desc[phase],'Conceptual sequence, not measured cell counts, timing or a clinical prediction. Immune pathways overlap and vary. Vaccination can establish memory without the full risks of the corresponding disease.');Q('#exStep').disabled=phase===4;Q('#exPrev').disabled=phase===0;Q('#exSource').innerHTML='<a class="small" href="https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-1-principles-of-vaccination.html" target="_blank" rel="noopener">CDC: principles of immune memory ↗</a>';}
function draw(){({motion,evolution,atoms,reactions,immunity}[topic])();}root.querySelectorAll('[data-explorer]').forEach(b=>b.onclick=()=>{topic=b.dataset.explorer;render()});window.addEventListener('science-model-topic',e=>{if(meta[e.detail]){topic=e.detail;render();root.scrollIntoView({behavior:reduce?'auto':'smooth'});}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});render();
})();
